final class TwViewModel {
    let root = SCNNode()
    private var guns: [String: SCNNode] = [:]
    private var flashes: [String: SCNNode] = [:]
    private var shown = ""
    private var mats: [String: SCNMaterial] = [:]
    private let k: Float = 0.17

    init() {
        root.scale = SCNVector3(k, k, k)
        root.isHidden = true
        guard let d = TwVMData.json.data(using: .utf8),
              let o = try? JSONSerialization.jsonObject(with: d) as? [String: Any] else { return }
        for (id, v) in o {
            guard let rig = v as? [String: Any], let parts = rig["parts"] as? [[String: Any]] else { continue }
            let g = SCNNode()
            g.isHidden = true
            var order = 1000
            for p in parts {
                guard let t = p["t"] as? String, let m = p["m"] as? String,
                      let pos = p["p"] as? [Double], let q = p["q"] as? [Double], let s = p["s"] as? [Double] else { continue }
                let geo: SCNGeometry
                var sc = SCNVector3(1, 1, 1)
                switch t {
                case "box":
                    let b = SCNBox(width: CGFloat(s[0]), height: CGFloat(s[1]), length: CGFloat(s[2]), chamferRadius: 0.03)
                    geo = b
                case "cyl":
                    let c = SCNCylinder(radius: CGFloat(s[0]), height: CGFloat(s[1]))
                    c.radialSegmentCount = 20
                    geo = c
                case "sph":
                    let sp = SCNSphere(radius: 1)
                    sp.segmentCount = 16
                    geo = sp
                    sc = SCNVector3(Float(s[0]), Float(s[1]), Float(s[2]))
                default:
                    let c = SCNCapsule(capRadius: CGFloat(s[0]), height: CGFloat(s[1]))
                    c.radialSegmentCount = 14
                    c.capSegmentCount = 6
                    geo = c
                }
                geo.firstMaterial = material(m)
                let n = SCNNode(geometry: geo)
                n.position = SCNVector3(Float(pos[0]), Float(pos[1]), Float(pos[2]))
                n.orientation = SCNVector4(Float(q[0]), Float(q[1]), Float(q[2]), Float(q[3]))
                n.scale = sc
                n.renderingOrder = order
                n.castsShadow = false
                order += 1
                g.addChildNode(n)
            }
            if let mz = rig["muzzle"] as? [Double] {
                let f = SCNNode(geometry: SCNSphere(radius: 2.2))
                let fm = SCNMaterial()
                fm.lightingModel = .constant
                fm.diffuse.contents = UIColor(red: 1, green: 0.85, blue: 0.4, alpha: 1)
                fm.emission.contents = UIColor(red: 1, green: 0.8, blue: 0.3, alpha: 1)
                fm.readsFromDepthBuffer = false
                fm.writesToDepthBuffer = false
                f.geometry?.firstMaterial = fm
                f.scale = SCNVector3(1, 1, 1.8)
                f.position = SCNVector3(Float(mz[0]), Float(mz[1]), Float(mz[2]) - 1)
                f.renderingOrder = 2000
                f.isHidden = true
                f.castsShadow = false
                g.addChildNode(f)
                flashes[id] = f
            }
            root.addChildNode(g)
            guns[id] = g
        }
    }

    static var gloveColor = UIColor(red: 0.165, green: 0.153, blue: 0.137, alpha: 1)

    private func material(_ name: String) -> SCNMaterial {
        if let m = mats[name] { return m }
        let m = SCNMaterial()
        func c(_ r: CGFloat, _ g: CGFloat, _ b: CGFloat) -> UIColor { UIColor(red: r, green: g, blue: b, alpha: 1) }
        m.lightingModel = .blinn
        m.specular.contents = UIColor(white: 0.25, alpha: 1)
        m.shininess = 0.2
        switch name {
        case "steel": m.diffuse.contents = c(0.36, 0.37, 0.39); m.specular.contents = UIColor(white: 0.8, alpha: 1); m.shininess = 0.5
        case "dark": m.diffuse.contents = c(0.08, 0.085, 0.09)
        case "poly": m.diffuse.contents = c(0.14, 0.145, 0.16)
        case "skin": m.diffuse.contents = c(0.85, 0.64, 0.5); m.specular.contents = UIColor(white: 0.1, alpha: 1)
        case "glove": m.diffuse.contents = TwViewModel.gloveColor; m.specular.contents = UIColor(white: 0.05, alpha: 1)
        case "knuckle": m.diffuse.contents = c(0.1, 0.094, 0.086); m.specular.contents = UIColor(white: 0.1, alpha: 1)
        case "strap": m.diffuse.contents = c(0.42, 0.35, 0.23); m.specular.contents = UIColor(white: 0, alpha: 1)
        case "nail": m.diffuse.contents = c(0.94, 0.8, 0.72)
        case "sleeve": m.diffuse.contents = c(0.3, 0.34, 0.21); m.specular.contents = UIColor(white: 0, alpha: 1)
        case "sleeveDark": m.diffuse.contents = c(0.18, 0.21, 0.13); m.specular.contents = UIColor(white: 0, alpha: 1)
        case "brass": m.diffuse.contents = c(0.8, 0.6, 0.23); m.specular.contents = UIColor(white: 0.9, alpha: 1)
        case "wood": m.diffuse.contents = c(0.48, 0.3, 0.16)
        case "glass":
            m.diffuse.contents = c(0.2, 0.5, 0.75)
            m.emission.contents = c(0.04, 0.16, 0.28)
        case "dot":
            m.lightingModel = .constant
            m.diffuse.contents = c(1, 0.1, 0.1)
        default:
            m.lightingModel = .constant
            m.diffuse.contents = c(0.95, 0.95, 0.95)
        }
        mats[name] = m
        return m
    }

    func show(_ id: String) {
        let gid = guns[id] != nil ? id : "pistol"
        if gid == shown { return }
        shown = gid
        for (key, n) in guns { n.isHidden = key != gid }
    }

    func flash(_ on: Bool) {
        flashes[shown]?.isHidden = !on
    }
}
